class MethodTypesDemo {

    // No parameters and no return value
    public static void add() {
        int a = 10;
        int b = 20;
        System.out.println(a + b);
    }

    // No parameters but returns a value
    public static int subtract() {
        int a = 10;
        int b = 20;
        return a - b;
    }

    // Accepts parameters but returns no value
    public static void multiply(int m, int n) {
        System.out.println(m * n);
    }

    // Accepts parameters and returns a value
    public static int divide(int x, int y) {
        return x / y;
    }

    public static void main(String[] args) {
        add();

        int subtractionResult = subtract();
        System.out.println(subtractionResult);

        multiply(10, 20);

        int divisionResult = divide(10, 2);
        System.out.println(divisionResult);
    }
}

